<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class PracticeStudentController extends Controller{
private function student(Request $r){abort_unless($r->user()->student_id,403);return $r->user()->student_id;}
private function placement(Request $r,$id){$sid=$this->student($r);$x=DB::table('practice_placements')->where(['id'=>$id,'student_id'=>$sid])->first();abort_if(!$x,404);return $x;}
public function index(Request $r){$sid=$this->student($r);$rows=DB::table('practice_placements')->where('student_id',$sid)->orderByDesc('starts_on')->get();$active=$rows->first(fn($x)=>in_array($x->status,['planned','active'])&&$x->ends_on>=date('Y-m-d'))?:$rows->first();if($active)$this->sync($active,$sid);$notifications=DB::table('practice_student_notifications')->where('student_id',$sid)->whereNull('read_at')->orderByDesc('id')->get();$progress=$active?$this->progress($active):null;$diary=$active?DB::table('practice_diary_entries')->where('practice_placement_id',$active->id)->orderByDesc('work_date')->get():collect();$photos=$active?DB::table('practice_photo_reports')->where('practice_placement_id',$active->id)->orderByDesc('id')->limit(12)->get():collect();return view('practice-office.student',compact('rows','active','notifications','progress','diary','photos'));}
public function diary(Request $r,$placement){$x=$this->placement($r,$placement);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['work_date'=>'required|date','hours'=>'required|numeric|min:0.25|max:24','work_description'=>'required|string|max:10000','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','location_accuracy'=>'nullable|numeric|min:0|max:100000']);abort_if($d['work_date']<$x->starts_on||$d['work_date']>$x->ends_on,422,'Дата вне срока практики');DB::table('practice_diary_entries')->updateOrInsert(['practice_placement_id'=>$x->id,'work_date'=>$d['work_date']],$d+['partner_status'=>'pending','partner_confirmed_at'=>null,'partner_comment'=>null,'submitted_at'=>now(),'updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Запись дневника отправлена.');}
public function photo(Request $r,$placement){$x=$this->placement($r,$placement);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['photo'=>'required|image|max:10240','work_date'=>'nullable|date','caption'=>'nullable|string|max:1000']);$f=$r->file('photo');$path=$f->store('practice/photos/'.$placement,'local');DB::table('practice_photo_reports')->insert(['practice_placement_id'=>$placement,'work_date'=>$d['work_date']??null,'path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime'=>$f->getMimeType(),'size'=>$f->getSize(),'caption'=>$d['caption']??null,'uploaded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Фото добавлено.');}
public function report(Request $r,$placement){$x=$this->placement($r,$placement);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['student_report'=>'required|string|max:30000']);DB::table('practice_placements')->where('id',$x->id)->update(['student_report'=>$d['student_report'],'updated_at'=>now()]);DB::table('practice_document_checks')->updateOrInsert(['practice_placement_id'=>$x->id,'document_type'=>'report'],['status'=>'submitted','updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Итоговый отчёт отправлен.');}
public function read(Request $r,$id){$sid=$this->student($r);DB::table('practice_student_notifications')->where(['id'=>$id,'student_id'=>$sid])->update(['read_at'=>now(),'updated_at'=>now()]);return back();}
private function progress($x){$planned=(float)($x->planned_hours??0);if(!$planned&&$x->practice_campaign_id)$planned=(float)(DB::table('practice_campaigns')->where('id',$x->practice_campaign_id)->value('planned_hours')??0);$hours=(float)DB::table('practice_diary_entries')->where('practice_placement_id',$x->id)->where('partner_status','confirmed')->sum('hours');$total=DB::table('practice_diary_entries')->where('practice_placement_id',$x->id)->count();$confirmed=DB::table('practice_diary_entries')->where('practice_placement_id',$x->id)->where('partner_status','confirmed')->count();return ['planned'=>$planned,'hours'=>$hours,'percent'=>$planned?min(100,round($hours*100/$planned)):0,'total'=>$total,'confirmed'=>$confirmed,'pending'=>$total-$confirmed];}
private function sync($x,$sid){$pending=DB::table('practice_diary_entries')->where('practice_placement_id',$x->id)->where('partner_status','pending')->count();if($pending)$this->notify($x,$sid,'pending','Неподтверждённые дни','Предприятие ещё не подтвердило записей дневника: '.$pending);if($x->ends_on>=date('Y-m-d')&&$x->ends_on<=date('Y-m-d',strtotime('+7 days'))&&!$x->student_report)$this->notify($x,$sid,'report','Срок практики завершается','До окончания практики осталось не более 7 дней. Подготовьте итоговый отчёт.');}
private function notify($x,$sid,$type,$title,$message){$fp='practice:'.$x->id.':'.$type.':'.date('Y-m-d');DB::table('practice_student_notifications')->insertOrIgnore(['practice_placement_id'=>$x->id,'student_id'=>$sid,'type'=>$type,'fingerprint'=>$fp,'title'=>$title,'message'=>$message,'created_at'=>now(),'updated_at'=>now()]);}
}